def parse_duration(text: str) -> float:
    """Parse a duration string and return the number of seconds as a float.

    Accepts a plain non-negative integer representing seconds, or a sequence
    of components with units d (days), h (hours), m (minutes), s (seconds),
    ms (milliseconds). Components must be in descending order of units and
    each unit may appear at most once. Whitespace is allowed around the
    string and between components, but not between a number and its unit.
    """
    if not isinstance(text, str):
        raise TypeError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")
    i = 0
    total = 0.0
    seen_units = set()
    prev_order = -1  # ensures descending order
    while i < len(s):
        # skip whitespace before a component
        while i < len(s) and s[i].isspace():
            i += 1
        if i >= len(s):
            break  # trailing whitespace
        # parse number
        start_num = i
        while i < len(s) and s[i].isdigit():
            i += 1
        if start_num == i:
            raise ValueError(f"missing number in duration: {text!r}")
        num_str = s[start_num:i]
        # after number, check for whitespace (invalid unless end)
        if i < len(s) and s[i].isspace():
            # skip whitespace
            while i < len(s) and s[i].isspace():
                i += 1
            if i >= len(s):
                # reached end after whitespace -> plain seconds
                total += int(num_str)
                break
            else:
                # whitespace followed by non-whitespace -> invalid (number-unit gap)
                raise ValueError(f"invalid whitespace in duration: {text!r}")
        # no whitespace after number
        if i >= len(s):
            # end of string -> plain seconds
            total += int(num_str)
            break
        # parse unit
        if s[i:i+2] == 'ms':
            unit = 'ms'
            i += 2
        else:
            unit = s[i]
            if unit not in ('d', 'h', 'm', 's'):
                raise ValueError(f"unknown unit in duration: {text!r}")
            i += 1
        # check repeated unit
        if unit in seen_units:
            raise ValueError(f"repeated unit in duration: {text!r}")
        seen_units.add(unit)
        # order check
        order = {'d':0, 'h':1, 'm':2, 's':3, 'ms':4}[unit]
        if order <= prev_order:
            raise ValueError(f"units out of order in duration: {text!r}")
        prev_order = order
        # add to total
        num = int(num_str)
        if unit == 'd':
            total += num * 86400
        elif unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
        elif unit == 'ms':
            total += num / 1000.0
    return float(total)

